SELECT E.ENO, D.DNAME
  FROM EMP E, DEPT D
 WHERE E.DNO = D.DNO;

SELECT D.DNAME, E.ENO
  FROM EMP E, DEPT D
 WHERE E.DNO(+) = D.DNO;

SELECT E.ENO, D.DNAME, L.CITY
  FROM EMP E, DEPT D, LOC L
 WHERE E.DNO = D.DNO;

SELECT E.ENO, G.GNO
  FROM EMP E, GRADE G
 WHERE E.SAL BETWEEN G.LO AND G.HI;

SELECT E.ENO, D.DNAME
  FROM EMP E, DEPT D
 WHERE E.DNO = D.DNO;

SELECT COUNT(*) AS CNT
  FROM PROD A, PROD B
 WHERE A.PRICE < B.PRICE;

SELECT E.ENO, D.DNAME
  FROM EMP E, DEPT D
 WHERE D.DNO = 10;

SELECT E.ENO, D.DNAME
  FROM EMP E, DEPT D
 WHERE E.DNO = D.DNO;
